    do {
        CK(0xC039);
        A = 0x99;                                    /* LC039 */
        X = (uint16_t)(X - 1);
        A = (uint8_t)(A - rd8(X));                   /* LC03B */
        A = add8(A, M8(TMPCNT));                     /* LC03D */
        daa_a();                                     /* LC040 */
        wr8(X, A);                                   /* LC041 */
        CYC(22);
        if (!CCC) {                                  /* LC043  IFCC  PROPAGATE THE CARRY */
            M8(TMPCNT) = 0;                          /* LC045 */
            CYC(10);
        } else {                                     /* LC048  ELSE   */
            A = 0x01;                                /* LC04A */
            M8(TMPCNT) = A;                          /* LC04C */
            CYC(7);
        }
        B = (uint8_t)(B - 1);                        /* LC04F */
        CYC(5);
    } while (!(B & 0x80));                           /* LC050  MIEND   */
    B = 0xFF;                                        /* LC052 */
    CYC(2);
    do {
        CK(0xC054);
        B = (uint8_t)(B + 1);                        /* LC054 */
        CYC(7);
        if (B == 0xEF) goto l_divide_40;             /* LC057  OVERFLOW---LEAVE AT MAX */
        A = M8(TEMP2+3);                             /* LC059  START WITH LSB */
        A = add8(A, M8(TEMP+3));                     /* LC05C  SUBTRACT DENOMINATOR ( ADD NEGATIVE IN DECIMAL) */
        daa_a();                                     /* LC05F */
        M8(TEMP2+3) = A;                             /* LC060 */
        A = M8(TEMP2+2);                             /* LC063 */
        A = adc8(A, M8(TEMP+2));                     /* LC066 */
        daa_a();                                     /* LC069 */
        M8(TEMP2+2) = A;                             /* LC06A */
        A = M8(TEMP2+1);                             /* LC06D */
        A = adc8(A, M8(TEMP+1));                     /* LC070 */
        daa_a();                                     /* LC073 */
        M8(TEMP2+1) = A;                             /* LC074 */
        A = M8(TEMP2+0);                             /* LC077 */
        A = adc8(A, M8(TEMP+0));                     /* LC07A */
        daa_a();                                     /* LC07D */
        M8(TEMP2+0) = A;                             /* LC07E */
        CYC(71);
    } while (CCC);                                   /* LC081  CCEND  DONE WHEN STAYS NEGATIVE ( DECIMAL ) NO CARRY */
