/* EEACCU ($C09D) - UPDATE COIN ACCOUNTING INFO IN EEROM
 */
void eeaccu(void)
{
    CK(0xC09D);
    A = 0x02;                                        /* LC09D  VERIFY AREA 2 */
    CYC(10);
    JSR(summit);                                     /* LC09F  CALCULATES CHECKSUM WITHOUT STORING */
    CYC(3);
    if (CCZ) {                                       /* LC0A2  IFEQ  CHECKSUM OK, THEN CONTINUE-- ELSE BAD DATA */
        A = 0;                                       /* LC0A4  START WITH 0 */
        B = M8(S_CCTIM);                             /* LC0A5  GET COIN COUNTER DATA-ALL 3 */
        B = asl8(B);                                 /* LC0A8  ASLD  GET COUNTER DATA INTO A */
        A = rol8(A);                                 /* LC0A9  ASLD  GET COUNTER DATA INTO A */
        B = M8(S_CCTIM+1);                           /* LC0AA */
        B = asl8(B);                                 /* LC0AD  ASLD   */
        A = rol8(A);                                 /* LC0AE  ASLD   */
        B = M8(S_CCTIM+2);                           /* LC0AF */
        B = asl8(B);                                 /* LC0B2  ASLD   */
        A = rol8(A);                                 /* LC0B3  ASLD   */
        B = A;                                       /* LC0B4  NEW DATA IN B */
        B ^= M8(EECOIN);                             /* LC0B6  1=CHANGE IN STATE */
        B &= M8(EECOIN);                             /* LC0B9  1=COIN COUNTER JUST TURNED ON */
        M8(EECOIN) = A;                              /* LC0BC  NEW STATE */
        X = RMECH;                                   /* LC0BF */
        CYC(53);
        do {
            CK(0xC0C2);
            B = lsr8(B);                             /* LC0C2 */
            CYC(5);
            if (CCC) {                               /* LC0C3  IFCS   */
                U = ITEMP;                           /* LC0C5 */
                CYC(11);
                JSR(eetmp2);                         /* LC0C8  MOVE EE TO TEMP */
                A = M8(ITEMP+2);                     /* LC0CB  LSB */
                A = add8(A, 0x01);                   /* LC0CE */
                daa_a();                             /* LC0D0 */
                M8(ITEMP+2) = A;                     /* LC0D1 */
                A = M8(ITEMP+1);                     /* LC0D4 */
                A = adc8(A, 0x00);                   /* LC0D7 */
                daa_a();                             /* LC0D9 */
                M8(ITEMP+1) = A;                     /* LC0DA */
                A = M8(ITEMP+0);                     /* LC0DD */
                A = adc8(A, 0x00);                   /* LC0E0 */
                daa_a();                             /* LC0E2 */
                M8(ITEMP+0) = A;                     /* LC0E3 */
                U = ITEMP;                           /* LC0E6 */
                CYC(53);
                JSR(tmpee2);                         /* LC0E9  PUT BACK IN EE ROM */
                A = 0x02;                            /* LC0EC  CALCULATE CHECKSUM FOR AREA 2 */
                M8(ITEMP+3) = B;                     /* LC0EE  SAVE IT */
                CYC(15);
                JSR(eecksm);                         /* LC0F1 */
                B = M8(ITEMP+3);                     /* LC0F4  GET B BACK */
                CYC(5);
            }
            X = (uint16_t)(X - 6);                   /* LC0F7  NEXT MECH */
            /* CMPX AMECH */                         /* LC0F9  DONE? */
            CYC(12);
        } while (X >= AMECH);                        /* LC0FC  LOEND   */
    }
    CYC(5);
    RTS;                                             /* LC0FE */
}

