void eeacct(void)
{
    uint8_t t8;
    CK(0xC0FF);
    A = 0x02;                                        /* LC0FF */
    CYC(10);
    JSR(chkee);                                      /* LC101  MAKE SURE AREA 2 IS VALID */
    X = TTIME;                                       /* LC104  TOTAL GAME TIMES */
    CYC(11);
    JSR(eetemp);                                     /* LC107  GET TOTALS INTO TEMPS */
    A = M8(TEMP+3);                                  /* LC10A  ADD GAME TIME TO TOTAL */
    A = add8(A, M8(GTIME+1));                        /* LC10D */
    daa_a();                                         /* LC110 */
    M8(TEMP+3) = A;                                  /* LC111 */
    A = M8(TEMP+2);                                  /* LC114 */
    A = adc8(A, M8(GTIME+0));                        /* LC117 */
    daa_a();                                         /* LC11A */
    M8(TEMP+2) = A;                                  /* LC11B */
    A = M8(TEMP+1);                                  /* LC11E */
    A = adc8(A, 0x00);                               /* LC121 */
    daa_a();                                         /* LC123 */
    M8(TEMP+1) = A;                                  /* LC124 */
    A = M8(TEMP+0);                                  /* LC127 */
    A = adc8(A, 0x00);                               /* LC12A */
    daa_a();                                         /* LC12C */
    CYC(60);
    if (!CCC) {                                      /* LC12D  IFCC  DO NOT OVERFLOW THE MSB */
        M8(TEMP+0) = A;                              /* LC12F */
        CYC(5);
    }
    A = 0x03;                                        /* LC132  DO FOUR BYTES */
    M8(TMPCNT) = B;                                  /* LC134 */
    U = TEMP;                                        /* LC137 */
    CYC(18);
    JSR(tmpee3);                                     /* LC13A  PUT DATA BACK TO EEROM */
    /* UPDATE NUMBER OF GAMES PLAYED */
    X = GAMES;                                       /* LC13D  NUMBER OF GAMES */
    CYC(11);
    JSR(eetemp);                                     /* LC140  PUT IT IN TEMPS */
    A = M8(TEMP+2);                                  /* LC143 */
    A = add8(A, 0x01);                               /* LC146 */
    daa_a();                                         /* LC148 */
    M8(TEMP+2) = A;                                  /* LC149 */
    A = M8(TEMP+1);                                  /* LC14C */
    A = adc8(A, 0x00);                               /* LC14F */
    daa_a();                                         /* LC151 */
    M8(TEMP+1) = A;                                  /* LC152 */
    A = M8(TEMP+0);                                  /* LC155 */
    A = adc8(A, 0x00);                               /* LC158 */
    daa_a();                                         /* LC15A */
    M8(TEMP+0) = A;                                  /* LC15B */
    CYC(50);
    JSR(tempee);                                     /* LC15E  PUT IT BACK IN EEROM */
    /* RECORD HIGHEST LEVEL EVER ATTAINED */
    X = ENDGAM;                                      /* LC161 */
    CYC(11);
    JSR(eetemp);                                     /* LC164  GET CURRENT HIGHEST TO TEMP */
    A = M8(GM_DWAV);                                 /* LC167  END OF GAME LEVEL ( IN BCD OR DECIMAL ) */
    /* CMPA M8(TEMP) */                              /* LC16A  COMPARE TO RECORDED LEVEL */
    CYC(13);
    if (A > M8(TEMP)) {                              /* LC16D  IFHI  THIS ONE IS HIGHER, USE IT INSTEAD */
        M8(TEMP) = A;                                /* LC16F */
        M8(TEMP+1) = 0;                              /* LC172  CLEAR UNUSED NIBBLES */
        M8(TEMP+2) = 0;                              /* LC175 */
        CYC(27);
        JSR(tempee);                                 /* LC178  PUT IT BACK INTO EEROM */
    }
    /* UPDATE HISTOGRAM INFO */
    X = (ZHISTOG-2);                                 /* LC17B  LAST ENTRY POINTER */
    A = M8(GTIME);                                   /* LC17E  MSB-IF NOT 0 THEN OVER 6:00, SO PUT IN LAST ENTRY */
    CYC(11);
    if (A == 0) {                                    /* LC181  IFEQ  FIND OUT WHERE TO PUT DATA */
        A = M8(GTIME+1);                             /* LC183 */
        X = HISTOG;                                  /* LC186  BEGINNING OF HISTOGRAM DATA */
        B = 0x9A;                                    /* LC189  GET NEGATIVE OF T.HIST ( THIS WON'T WORK FOR ALL) */
        B = (uint8_t)(B - rd8(T_HIST));              /* LC18B */
        M8(TEMP) = B;                                /* LC18E */
        CYC(20);
        do {
            CK(0xC191);
            A = add8(A, M8(TEMP));                   /* LC191 */
            daa_a();                                 /* LC194 */
            CYC(10);
            if (!CCC) goto l_eeacct_20;              /* LC195  FOUND ITS NICHE */
            X = (uint16_t)(X + 2);                   /* LC197 */
            CYC(12);
        } while (X < (ZHISTOG-2));                   /* LC19C  HSEND  IF NOT FOUND, PUT IN LAST ONE ANYWAY */
    }
l_eeacct_20:;
    CK(0xC19E);
    A = rd8((uint16_t)(X + 1));                      /* LC19E  ADD 1 */
    A &= 0x0F;                                       /* LC1A0 */
    A = add8(A, 0x01);                               /* LC1A2 */
    daa_a();                                         /* LC1A4 */
    wr8((uint16_t)(X + 1), A);                       /* LC1A5 */
    A &= 0xF0;                                       /* LC1A7 */
    CYC(21);
    if (A != 0) {                                    /* LC1A9  IFNE  UPDATE HI NIBBLE */
        A = rd8(X);                                  /* LC1AB */
        A &= 0x0F;                                   /* LC1AD */
        A = add8(A, 0x01);                           /* LC1AF */
        daa_a();                                     /* LC1B1 */
        wr8(X, A);                                   /* LC1B2 */
        A &= 0xF0;                                   /* LC1B4 */
        CYC(19);
        if (A != 0) {                                /* LC1B6  IFNE  OVERFLOW-BAD NEWS DIVIDE ALL HISTOGRAM VALUES BY 2 */
            X = HISTOG;                              /* LC1B8 */
            CYC(3);
            do {
                CK(0xC1BB);
                A = rd8(X);                          /* LC1BB */
                A = (uint8_t)(A << 1);               /* LC1BD */
                A = (uint8_t)(A << 1);               /* LC1BE */
                A = (uint8_t)(A << 1);               /* LC1BF */
                A = (uint8_t)(A << 1);               /* LC1C0 */
                M8(TEMP) = A;                        /* LC1C1 */
                A = rd8((uint16_t)(X + 1));          /* LC1C4 */
                A &= 0x0F;                           /* LC1C6 */
                A = (uint8_t)(A + M8(TEMP));         /* LC1C8 */
                t8 = (uint8_t)(A & 0x10);            /* LC1CB  WILL DIVIDE BY 2 WORK? */
                CYC(34);
                if (t8 != 0) {                       /* LC1CD  IFNE  NO */
                    A = (uint8_t)(A - 0x06);         /* LC1CF  THIS CORRECTS IT */
                    CYC(2);
                }
                A = (uint8_t)(A >> 1);               /* LC1D1 */
                wr8((uint16_t)(X + 1), A);           /* LC1D2 */
                A = (uint8_t)(A >> 1);               /* LC1D4 */
                A = (uint8_t)(A >> 1);               /* LC1D5 */
                A = (uint8_t)(A >> 1);               /* LC1D6 */
                A = (uint8_t)(A >> 1);               /* LC1D7 */
                wr8(X, A);                           /* LC1D8 */
                X = (uint16_t)(X + 2);               /* LC1DA */
                CYC(31);
            } while (X < ZHISTOG);                   /* LC1DF  HSEND   */
            A = 0x05;                                /* LC1E1  1/2 OF 100 IS 50 */
            wr8(U, A);                               /* LC1E3 */
            A = 0x00;                                /* LC1E5 */
            wr8((uint16_t)(U + 1), A);               /* LC1E7 */
            CYC(13);
        }
    }
    /* SAVE POT VALUES */
    A = M8(RHEOP+RHS_LO);                            /* LC1E9 */
    M8(TEMP) = A;                                    /* LC1EC */
    A = M8(RHEOP+RHS_SP);                            /* LC1EF */
    M8(TEMP+1) = A;                                  /* LC1F2 */
    A = M8(RHEOY+RHS_LO);                            /* LC1F5 */
    M8(TEMP+2) = A;                                  /* LC1F8 */
    A = M8(RHEOY+RHS_SP);                            /* LC1FB */
    M8(TEMP+3) = A;                                  /* LC1FE */
    X = POTSAV;                                      /* LC201  MOVE THEM FROM TEMP TO POTSAV IN EEROM */
    U = TEMP;                                        /* LC204 */
    A = 0x03;                                        /* LC207  4 BYTES WORTH */
    CYC(56);
    JSR(tmpee3);                                     /* LC209 */
    eeutim();                                        /* falls into EEUTIM */
}

/* EEUTIM ($C20C) - TIME TO UPDATE TIMEON
 * Condition codes out: C.
 */
void eeutim(void)
{
    uint16_t t16;
    CK(0xC20C);
    X = TIMEON;                                      /* LC20C  MOVE TIMEON FROM EEROM */
    CYC(11);
    JSR(eetemp);                                     /* LC20F */
    sw_sei();                                        /* LC212  SEI  STOPS INTERRUPT INTERACTION */
    U = rd16(TIMER+2);                               /* LC214  RAM BASED TIME */
    D = rd16(TIMER);                                 /* LC217 */
    nz16(D);
    CYC(15);
    sw_cli();                                        /* LC21A  CLI   */
    cmp16(D, rd16(TEMP));                            /* LC21C  NEW TIME SHOULD BE LARGER THAN OLD */
    CYC(14);
    if (!(CCC | CCZ)) goto l_eeutim_40;              /* LC220  OK USE THIS AS NEW TIME */
    CYC(3);
    if (CCC) goto l_eeutim_50;                       /* LC222  LESS, DON'T USE IT AND SET IT TO OLD */
    t16 = rd16(TEMP+2);                              /* LC224  CHECK THE LOWER BYTES */
    CYC(11);
    if (U <= t16) goto l_eeutim_50;                  /* LC228 */
l_eeutim_40:;
    CK(0xC22A);
    wr16(TEMP, D);                                   /* LC22A  SAVE NEW TIME */
    wr16(TEMP+2, U);                                 /* LC22D */
    X = TIMEON;                                      /* LC230 */
    U = TEMP;                                        /* LC233 */
    A = 0x03;                                        /* LC236 */
    CYC(28);
    JSR(tmpee3);                                     /* LC238  PUT IT BACK INTO EEROM */
    CYC(3);
    goto l_eeutim_60;                                /* LC23B */
l_eeutim_50:;
    CK(0xC23D);
    D = rd16(TEMP);                                  /* LC23D  RESTORE TIME FROM TIMEON */
    wr16(TIMER, D);                                  /* LC240 */
    D = rd16(TEMP+2);                                /* LC243 */
    wr16(TIMER+2, D);                                /* LC246 */
    CYC(24);
l_eeutim_60:;
    CK(0xC249);
    A = 0x02;                                        /* LC249  SET NEW CHECKSUM */
    CYC(6);
    eecksm(); return;                                /* LC24B  AND RETURN */
}

/* EECPY ($C24E) - RESTORE FROM ROM TABLE
 */
void eecpy(void)
{
    uint16_t t16;
    CK(0xC24E);
    /* CMPA NAREA */                                 /* LC24E  LEGAL? */
    CYC(5);
    if (A < NAREA) {                                 /* LC250  IFLO  YES, GO AHEAD PLEASE */
        /* CMPA 0x02 */                              /* LC252  AREAS 0 AND 1 GET DEFAULTS DIFFERENTLY */
        CYC(5);
        if (A >= 0x02) {                             /* LC254  IFHS  GET DEFAULTS FROM T.DFLT */
            X = (T_AREA+1);                          /* LC256  GET END OF AREA */
            B = rd8((uint16_t)(X + (int8_t)A));      /* LC259  POINTS TO SOMEWHERE IN EEROM PAGE */
            B = (uint8_t)(B - 0x02);                 /* LC25B  LIMIT IS FIRST NIBBLE OF CHECKSUM */
            M8(TEMP+1) = B;                          /* LC25D */
            B = 0x45;                                /* LC260  WHAT PAGE IS NON-VOLATILE RAM */
            M8(TEMP) = B;                            /* LC262  (TEMP,TEMP+1) IS LIMIT */
            X = T_AREA;                              /* LC265 */
            B = rd8((uint16_t)(X + (int8_t)A));      /* LC268  GET START OF AREA */
            X = (T_DFLT-(EECK1-EEROM+2));            /* LC26A  DEFAULT TABLE STARTS WITH AREA 2 */
            X = (uint16_t)(X + B);                   /* LC26D */
            U = X;                                   /* LC26E */
            X = EEROM;                               /* LC270 */
            X = (uint16_t)(X + B);                   /* LC273 */
            CYC(48);
            do {
                CK(0xC274);
                B = rd8(U);                          /* LC274 */
                U = (uint16_t)(U + 1);
                CYC(6);
                wr8(X, B);                           /* LC276 */
                X = (uint16_t)(X + 1);
                t16 = rd16(TEMP);                    /* LC278 */
                CYC(16);
            } while (X < t16);                       /* LC27B  HSEND   */
            CYC(3);
        } else {                                     /* LC27D  ELSE  ELSE GET DEFAULTS FROM ELSEWHERE */
            B = A;                                   /* LC27F  SAVE IT */
            /* TSTA */                               /* LC281 */
            CYC(11);
            if (A == 0) {                            /* LC282  IFEQ  OPTION SWITCHES----USE PHYSICAL SWITCHES FOR DEFAULT */
                A = M8(R_OPT1);                      /* LC284  COINS */
                M8(TEMP) = A;                        /* LC286 */
                A = M8(R_OPT2);                      /* LC289  STARTING LIVES,DIFFICULTY,BONUS SHIELDS,ATTRACTIVE MUSIC */
                M8(TEMP+1) = A;                      /* LC28B */
                A = 0x00;                            /* LC28E  SET FOR MISC. OPTIONS */
                M8(TEMP+2) = A;                      /* LC290 */
                X = DUPOPT;                          /* LC293  START OF AREA 0 */
                CYC(36);
                JSR(tempee);                         /* LC296 */
                CYC(3);
            } else {                                 /* LC299  ELSE  MUST BE HIGH SCORE INIT */
                X = SAVSCR;                          /* LC29B  DO SCORES FIRST */
                U = INTSCR;                          /* LC29E  INITIAL SCORE TABLE (SEE TCHSCR) */
                A = 0x0B;                            /* LC2A1 */
                CYC(16);
                JSR(tmpee3);                         /* LC2A3 */
                X = SAVINT;                          /* LC2A6  NOW FOR THE INITIALS */
                U = INTINT;                          /* LC2A9  INITIAL INITIALS TABLE (SEE TCHSCR) */
                A = 0x08;                            /* LC2AC */
                CYC(16);
                JSR(tmpee3);                         /* LC2AE */
            }
            A = B;                                   /* LC2B1  GET AREA NUMBER BACK INTO A */
            CYC(6);
        }
    }
    eecksm();                                        /* falls into EECKSM */
}

/* EECKSM ($C2B3) - AND RETURN
 * Condition codes out: NZVC.
 */
void eecksm(void)
{
    CK(0xC2B3);
    CYC(8);
    JSR(summit);                                     /* LC2B3  GET CHECKSUM, Z=1 IF CHECKSUM SAME, SUM IN B */
    CYC(3);
    if (!CCZ) {                                      /* LC2B6  IFNE  STORE IT */
        wr8((uint16_t)(X + 1), B);                   /* LC2B8  LO NIBBLE */
        B = (uint8_t)(B >> 1);                       /* LC2BA */
        B = (uint8_t)(B >> 1);                       /* LC2BB */
        B = (uint8_t)(B >> 1);                       /* LC2BC */
        B = lsr8(B);                                 /* LC2BD */
        CYC(13);
        wr8(X, B);                                   /* LC2BE  HI NIBBLE */
        B = 0xFF;                                    /* LC2C0  CLEAR ZERO FLAG */
        nz8(B);
        CYC(6);
    }
    CYC(5);
    RTS;                                             /* LC2C2 */
}

/* SUMMIT ($C2C3) - CHECK FOR PROPER CHECKSUM
 * Condition codes out: NZVC.
 */
void summit(void)
{
    uint8_t t8;
    CK(0xC2C3);
    S = (uint16_t)(S - 3);                           /* LC2C3  ALLOCATE 3 BYTES */
    X = (T_AREA+1);                                  /* LC2C5  GET LENGHT OF AREA */
    B = rd8((uint16_t)(X + (int8_t)A));              /* LC2C8 */
    X = T_AREA;                                      /* LC2CA */
    B = (uint8_t)(B - rd8((uint16_t)(X + (int8_t)A))); /* LC2CD */
    B = sub8(B, 0x02);                               /* LC2CF  DON'T CHECKSUM THE CHECKSUM */
    wr8(S, B);                                       /* LC2D1 */
    B = rd8((uint16_t)(X + (int8_t)A));              /* LC2D3  GET START OF AREA */
    X = EEROM;                                       /* LC2D5 */
    X = (uint16_t)(X + B);                           /* LC2D8  POINTS TO START OF AREA TO CHECKSUM */
    B = 0x00;                                        /* LC2D9  SEED */
    wr8((uint16_t)(S + NEWSUM), B);                  /* LC2DB */
    nz8(B);
    CCC = 1;                                         /* LC2DD  SEC  PREVENT A ZERO CHECKSUM */
    CYC(48);
    do {
        CK(0xC2DF);
        B = rd8(X);                                  /* LC2DF  GET DATA */
        X = (uint16_t)(X + 1);
        B &= 0x0F;                                   /* LC2E1  ONLY LOWER NIBBLE IS DATA */
        B = adc8(B, rd8((uint16_t)(S + NEWSUM)));    /* LC2E3  SUM */
        wr8((uint16_t)(S + NEWSUM), B);              /* LC2E5 */
        t8 = dec8(rd8(S));                           /* LC2E7 */
        wr8(S, t8);
        CYC(27);
    } while (t8 != 0);                               /* LC2E9  EQEND   */
    B = adc8(B, 0x00);                               /* LC2EB  GET ALL THE CARRIES IN */
    wr8((uint16_t)(S + NEWSUM), B);                  /* LC2ED */
    /* COMPARE WITH OLD CHECKSUM */
    CYC(7);
    B = rd8(X);                                      /* LC2EF  HI NIBBLE */
    B = (uint8_t)(B << 1);                           /* LC2F1 */
    B = (uint8_t)(B << 1);                           /* LC2F2 */
    B = (uint8_t)(B << 1);                           /* LC2F3 */
    B = (uint8_t)(B << 1);                           /* LC2F4 */
    wr8((uint16_t)(S + OLDSUM), B);                  /* LC2F5 */
    CYC(17);
    B = rd8((uint16_t)(X + 1));                      /* LC2F7  LO NIBBLE */
    B &= 0x0F;                                       /* LC2F9 */
    B = (uint8_t)(B + rd8((uint16_t)(S + OLDSUM)));  /* LC2FB  OLD CHECKSUM */
    wr8((uint16_t)(S + OLDSUM), B);                  /* LC2FD */
    B = rd8((uint16_t)(S + NEWSUM));                 /* LC2FF */
    cmp8(B, rd8((uint16_t)(S + OLDSUM)));            /* LC301  SET CONDITION CODE */
    S = (uint16_t)(S + 3);                           /* LC303  RESTORE STACK POINTER */
    CYC(37);
    RTS;                                             /* LC305 */
}

/* EEINIT ($C306) - INIT EEROM ( VERIFY/SET NOVRAM AREAS TO VALID STATES )
 */
void eeinit(void)
{
    CK(0xC306);
    X = EEROM;                                       /* LC306  COPY EEROM TO BUFFER */
    U = EEBUF;                                       /* LC309 */
    CYC(6);
    do {
        CK(0xC30C);
        D = rd16(X);                                 /* LC30C */
        X = (uint16_t)(X + 2);
        wr16(U, D);                                  /* LC30E */
        U = (uint16_t)(U + 2);
        CYC(23);
    } while (X < EEROMZ);                            /* LC313  HSEND   */
    A = 0xFF;                                        /* LC315  PERFORM A RECALL OF THE NON-VOLATILE MEMORY */
    CYC(2);
    hw_wr8(NVRRCL, A);                               /* LC317 */
    X = 0x0100;                                      /* LC31A  WAIT FOR THE CAP TO DISCHARGE */
    CYC(8);
    do {
        CK(0xC31D);
        hw_wr8(WTCHDG, A);                           /* LC31D */
        X = (uint16_t)(X - 1);                       /* LC320 */
        CYC(13);
    } while (X != 0);                                /* LC322  EQEND   */
    A = 0x00;                                        /* LC324  TURN OFF RECALL LINE */
    CYC(2);
    hw_wr8(NVRRCL, A);                               /* LC326 */
    X = 0xA000;                                      /* LC329  NOW WAIT FOR THE CAP TO CHARGE BACK UP */
    CYC(8);
    do {
        CK(0xC32C);
        hw_wr8(WTCHDG, A);                           /* LC32C */
        X = (uint16_t)(X - 1);                       /* LC32F */
        CYC(13);
    } while (X != 0);                                /* LC331  EQEND   */
    X = EEROM;                                       /* LC333  SWAP EEROM AND BUFFER */
    Y = EEBUF;                                       /* LC336 */
    CYC(7);
    do {
        CK(0xC33A);
        U = rd16(X);                                 /* LC33A */
        D = rd16(Y);                                 /* LC33C */
        wr16(Y, U);                                  /* LC33E */
        Y = (uint16_t)(Y + 2);
        CYC(18);
        wr16(X, D);                                  /* LC340 */
        X = (uint16_t)(X + 2);
        CYC(15);
    } while (X < EEROMZ);                            /* LC345  HSEND  EEBUF HAS RECALLED DATA AND EEROM HAS ITS ORIGINAL */
    /* START CHECKING VALIDITY */
    A = NAREA;                                       /* LC347  OPTION SWITCH AREA IS SPECIAL, 2 AREAS */
    CYC(10);
    JSR(summit);                                     /* LC349 */
    CYC(3);
    if (CCZ) { eeinit_20(); return; }                /* LC34C  PRIMARY OK, MAKE SURE BACKUP IS OK */
    A = 0x00;                                        /* LC34E  PRIMARY WAS BAD, CHECK BACKUP AREA */
    CYC(10);
    JSR(summit);                                     /* LC350 */
    CYC(3);
    if (CCZ) { eeinit_15(); return; }                /* LC353  BACKUP OK, GO REWRITE MAIN AREA FROM BACKUP */
    /* BOTH RAM AREAS BAD, CHECK RECALLED DATA */
    CYC(8);
    JSR(eeini2);                                     /* LC355  RESTORE PRIMARY AND BACKUP FROM EEBUFF COPY */
    A = NAREA;                                       /* LC358 */
    CYC(10);
    JSR(eeini2);                                     /* LC35A */
    CYC(8);
    JSR(summit);                                     /* LC35D  CHECKSUM RECALLED PRIMARY */
    CYC(3);
    if (CCZ) { eeinit_20(); return; }                /* LC360  'TWAS OK, CHECK NEW BACKUP */
    A = 0x00;                                        /* LC362  NEW PRIMARY BAD, CHECK NEW BACKUP */
    CYC(10);
    JSR(summit);                                     /* LC364 */
    CYC(3);
    if (CCZ) { eeinit_15(); return; }                /* LC367 */
    eeini0();                                        /* falls into EEINI0 */
}

/* EEINI0 ($C369) - THEN RE-INIT IT
 * Condition codes out: C.
 */
void eeini0(void)
{
    CK(0xC369);
    CYC(8);
    JSR(eecpy);                                      /* LC369  RESTORE FROM ROM TABLE */
    eeinit_15();                                     /* falls into EEINIT_15 */
}

/* EEINIT_15 ($C36C)
 * Condition codes out: C.
 */
void eeinit_15(void)
{
    CK(0xC36C);
    X = T_AREA;                                      /* LC36C  MOVE BACKUP TO PRIMARY */
    B = rd8((uint16_t)(X + NAREA));                  /* LC36F */
    X = EEROM;                                       /* LC373 */
    X = (uint16_t)(X + B);                           /* LC376  POINTER TO BAD AREA */
    U = EEROM;                                       /* LC377  POINTER TO GOOD AREA (BACKUP) */
    CYC(23);
    eeinit_40(); return;                             /* LC37A  FIX IT FROM BACKUP */
}

/* EEINIT_20 ($C37C)
 */
void eeinit_20(void)
{
    CK(0xC37C);
    A = 0x00;                                        /* LC37C  CHECK THE BACKUP AREA */
    CYC(10);
    JSR(summit);                                     /* LC37E */
    CYC(3);
    if (!CCZ) { eeini1(); return; }                  /* LC381  FIX IT FROM PRIMARY */
    /* BOTH AREAS HAVE GOOD CHECKSUMS, MAKE AREAS THE SAME */
    A = hw_rd8(EECK3);                               /* LC383  PRIMARY OPTION SWITCH CHECKSUM */
    A &= 0x0F;                                       /* LC386 */
    M8(TEMP) = A;                                    /* LC388 */
    CYC(12);
    A = hw_rd8(EECK0);                               /* LC38B  BACKUP */
    A &= 0x0F;                                       /* LC38E */
    cmp8(A, M8(TEMP));                               /* LC390 */
    CYC(15);
    if (CCZ) {                                       /* LC393  IFEQ   */
        A = hw_rd8(EECK3+1);                         /* LC395 */
        A &= 0x0F;                                   /* LC398 */
        M8(TEMP) = A;                                /* LC39A */
        CYC(12);
        A = hw_rd8(EECK0+1);                         /* LC39D */
        A &= 0x0F;                                   /* LC3A0 */
        cmp8(A, M8(TEMP));                           /* LC3A2 */
        CYC(12);
    }
    CYC(3);
    if (CCZ) { eeinit_55(); return; }                /* LC3A5  OPTION SWITCH CHECKSUM ARE THE SAME, CHECK OTHER AREAS */
    eeini1();                                        /* falls into EEINI1 */
}

/* EEINI1 ($C3A7) - SETUP BACKUP AND CHECK OTHER AREAS
 */
void eeini1(void)
{
    CK(0xC3A7);
    X = T_AREA;                                      /* LC3A7  REPLACE BACKUP AREA WITH PRIMARY */
    B = rd8((uint16_t)(X + NAREA));                  /* LC3AA */
    X = EEROM;                                       /* LC3AE */
    X = (uint16_t)(X + B);                           /* LC3B1 */
    U = X;                                           /* LC3B2  POINTS TO PRIMARY OPTION SWITCH AREA */
    X = EEROM;                                       /* LC3B4  POINTS TO BACKUP OPTION SWITCH AREA */
    CYC(26);
    eeinit_40();                                     /* falls into EEINIT_40 */
}

/* EEINIT_40 ($C3B7)
 * Condition codes out: C.
 */
void eeinit_40(void)
{
    CK(0xC3B7);
    B = rd8(T_AREA+1);                               /* LC3B7  LENGTH OF OPTION SWITCH AREAS */
    M8(TMPCNT) = B;                                  /* LC3BA */
    CYC(10);
    do {
        CK(0xC3BD);
        B = rd8(U);                                  /* LC3BD  TRANSFER GOOD TO BAD */
        U = (uint16_t)(U + 1);
        CYC(6);
        wr8(X, B);                                   /* LC3BF */
        X = (uint16_t)(X + 1);
        M8(TMPCNT) = (uint8_t)(M8(TMPCNT) - 1);      /* LC3C1 */
        CYC(16);
    } while (M8(TMPCNT) != 0);                       /* LC3C4  EQEND   */
    eeinit_55();                                     /* falls into EEINIT_55 */
}

/* EEINIT_55 ($C3C6)
 * Condition codes out: C.
 */
void eeinit_55(void)
{
    CK(0xC3C6);
    A = (NAREA-1);                                   /* LC3C6  NEXT AREA */
    CYC(2);
    do {
        CK(0xC3C8);
        CYC(8);
        JSR(summit);                                 /* LC3C8 */
        CYC(3);
        if (!CCZ) {                                  /* LC3CB  IFNE  NO GOOD */
            CYC(8);
            JSR(eeini2);                             /* LC3CD  REPLACE FROM BUFFER */
            CYC(8);
            JSR(summit);                             /* LC3D0 */
            CYC(3);
            if (!CCZ) {                              /* LC3D3  IFNE  REALLY BAD, USE DEFAULTS */
                CYC(8);
                JSR(eecpy);                          /* LC3D5 */
            }
        }
        A = (uint8_t)(A - 1);                        /* LC3D8 */
        CYC(5);
    } while (A != 0);                                /* LC3D9  EQEND   */
    X = TIMEON;                                      /* LC3DB  SETUP RAM BASED TIME ON */
    CYC(11);
    JSR(eetemp);                                     /* LC3DE */
    D = rd16(TEMP);                                  /* LC3E1 */
    wr16(TIMER, D);                                  /* LC3E4 */
    D = rd16(TEMP+2);                                /* LC3E7 */
    wr16(TIMER+2, D);                                /* LC3EA */
    CYC(29);
    RTS;                                             /* LC3ED */
}

/* EEINI2 ($C3EE) - RESTORE PRIMARY AND BACKUP FROM EEBUFF COPY
 */
void eeini2(void)
{
    uint16_t t16;
    CK(0xC3EE);
    X = (T_AREA+1);                                  /* LC3EE */
    B = rd8((uint16_t)(X + (int8_t)A));              /* LC3F1 */
    X = EEROM;                                       /* LC3F3 */
    X = (uint16_t)(X + B);                           /* LC3F6 */
    wr16(TEMP, X);                                   /* LC3F7  START OF NEXT AREA */
    X = T_AREA;                                      /* LC3FA */
    B = rd8((uint16_t)(X + (int8_t)A));              /* LC3FD */
    X = EEBUF;                                       /* LC3FF */
    X = (uint16_t)(X + B);                           /* LC402 */
    U = X;                                           /* LC403  START OF AREA IN EEBUF */
    X = EEROM;                                       /* LC405 */
    X = (uint16_t)(X + B);                           /* LC408  START OF AREA IN EEROM */
    CYC(46);
    do {
        CK(0xC409);
        B = rd8(U);                                  /* LC409 */
        U = (uint16_t)(U + 1);
        CYC(6);
        wr8(X, B);                                   /* LC40B */
        X = (uint16_t)(X + 1);
        t16 = rd16(TEMP);                            /* LC40D */
        CYC(16);
    } while (X < t16);                               /* LC410  HSEND   */
    CYC(5);
    RTS;                                             /* LC412 */
}

/* CHKEE ($C413) - MAKE SURE AREA 2 IS VALID
 */
void chkee(void)
{
    CK(0xC413);
    CYC(8);
    JSR(summit);                                     /* LC413 */
    CYC(3);
    if (!CCZ) {                                      /* LC416  IFNE  ERROR */
        M8(TEMP) = A;                                /* LC418  SAVE AREA NUMBER */
        X = EEROM;                                   /* LC41B  COPY EEROM TO BUFFER */
        U = EEBUF;                                   /* LC41E */
        CYC(11);
        do {
            CK(0xC421);
            D = rd16(X);                             /* LC421 */
            X = (uint16_t)(X + 2);
            wr16(U, D);                              /* LC423 */
            U = (uint16_t)(U + 2);
            CYC(23);
        } while (X < EEROMZ);                        /* LC428  HSEND   */
        CYC(8);
        JSR(novrcl);                                 /* LC42A  PERFORM A RECALL OF THE NON-VOLATILE RAM */
        X = EEROM;                                   /* LC42D  SWAP EEROM AND BUFFER */
        Y = EEBUF;                                   /* LC430 */
        CYC(7);
        do {
            CK(0xC434);
            U = rd16(X);                             /* LC434 */
            D = rd16(Y);                             /* LC436 */
            wr16(Y, U);                              /* LC438 */
            Y = (uint16_t)(Y + 2);
            wr16(X, D);                              /* LC43A */
            X = (uint16_t)(X + 2);
            CYC(33);
        } while (X < EEROMZ);                        /* LC43F  HSEND  EEBUF HAS RECALEED DATA AND EEROM HAS ITS ORIGINAL */
        A = M8(TEMP);                                /* LC441  RESTORE AREA NUMBER */
        CYC(13);
        JSR(eeini2);                                 /* LC444 */
        CYC(8);
        JSR(summit);                                 /* LC447 */
        CYC(3);
        if (!CCZ) {                                  /* LC44A  IFNE   */
            CYC(8);
            JSR(eecpy);                              /* LC44C */
        }
    }
    CYC(5);
    RTS;                                             /* LC44F */
}

/* EEOPT ($C450) - DISPLAY ALL OPTIONS
 */
void eeopt(void)
{
    CK(0xC450);
    A = MS_OPT;                                      /* LC450  OPTION SWITCH MESSAGES */
    CYC(2);
    do {
        CK(0xC452);
        CYC(8);
        JSR(messon);                                 /* LC452 */
        A = (uint8_t)(A + 1);                        /* LC455 */
        CYC(7);
    } while (A < MS_VLC);                            /* LC458  HSEND   */
    A = MS_TST;                                      /* LC45A  "AUX FOR SELF TEST" MESSAGE */
    CYC(10);
    JSR(messon);                                     /* LC45C */
    D = (VGCOLR+(VGCGRN*0x100));                     /* LC45F  OPTION SWITCH VALUE COLOR */
    wr16(Y, D);                                      /* LC462 */
    Y = (uint16_t)(Y + 2);
    A = (T_OPTZ-T_OPT-1);                            /* LC464  DISPLAY ALL OPTION SWITCH VALUES */
    M8(TEMP2) = A;                                   /* LC466 */
    CYC(18);
    do {
        CK(0xC469);
        A = M8(TEMP2);                               /* LC469 */
        CYC(13);
        JSR(eeopt3);                                 /* LC46C */
        M8(TEMP2) = (uint8_t)(M8(TEMP2) - 1);        /* LC46F */
        CYC(10);
    } while (!(M8(TEMP2) & 0x80));                   /* LC472  MIEND   */
    CYC(8);
    JSR(eetstr);                                     /* LC474  REPORT RESULTS OF EEROM ( NOVRAM ) TEST */
    A = hw_rd8(RESETS);                              /* LC477  CHECK FOR RESETS */
    A &= 0x0F;                                       /* LC47A */
    CYC(10);
    if (A != 0) {                                    /* LC47C  IFNE  SOMETHING NEEDS TO BE RESET */
        B = MS_RES;                                  /* LC47E  "USE RIGHT FIRE BUTTON TO PERFORM ANY RESET" */
        CYC(10);
        JSR(domess);                                 /* LC480 */
        A = M8(GN_SWE);                              /* LC483  CHECK FOR FIRE BUTTON */
        A &= RFIRBT;                                 /* LC485  RIGHT FIRE */
        CYC(9);
        if (A != 0) {                                /* LC487  IFNE  IT WAS PUSHED, RESET INDICATED AREAS */
            A = hw_rd8(RESETS);                      /* LC489 */
            A &= 0x08;                               /* LC48C  RESET HIGH SCORES? */
            CYC(10);
            if (A != 0) {                            /* LC48E  IFNE  YES */
                A = 0x01;                            /* LC490 */
                CYC(10);
                JSR(eecpy);                          /* LC492  PERFORM DEFAULT COPY ON AREA 1 */
                CYC(8);
                JSR(setint);                         /* LC495  RESET OTHER INITIALS TOO */
            }
            A = hw_rd8(RESETS);                      /* LC498 */
            A &= 0x04;                               /* LC49B  RESET ACCOUNTING INFO? */
            CYC(10);
            if (A != 0) {                            /* LC49D  IFNE  YES */
                X = GAMES;                           /* LC49F  CLEAR AREA 2 STARTING AT GAMES ( LEAVE COINS ALONE ) */
                D = 0x0000;                          /* LC4A2 */
                CYC(6);
                do {
                    CK(0xC4A5);
                    wr16(X, D);                      /* LC4A5  WORD STORE FOR 2 NIBBLES */
                    X = (uint16_t)(X + 2);
                    CYC(15);
                } while (X < EECK2);                 /* LC4AA  HSEND   */
                A = 0x02;                            /* LC4AC  CHECKSUM AREA 2 */
                CYC(10);
                JSR(eecksm);                         /* LC4AE */
            }
            A = hw_rd8(RESETS);                      /* LC4B1 */
            A &= 0x02;                               /* LC4B4  RESET OPTIONS TO DEFAULT? */
            CYC(10);
            if (A != 0) {                            /* LC4B6  IFNE  YES */
                A = 0x00;                            /* LC4B8  SET AREA 0 TO DEFAULT */
                CYC(10);
                JSR(eecpy);                          /* LC4BA */
                X = T_AREA;                          /* LC4BD  COPY BACKUP AREA TO PRIMARY AREA */
                B = rd8((uint16_t)(X + NAREA));      /* LC4C0 */
                X = EEROM;                           /* LC4C4 */
                X = (uint16_t)(X + B);               /* LC4C7 */
                U = EEROM;                           /* LC4C8 */
                B = rd8(T_AREA+1);                   /* LC4CB */
                M8(TMPCNT) = B;                      /* LC4CE */
                CYC(30);
                do {
                    CK(0xC4D1);
                    B = rd8(U);                      /* LC4D1 */
                    U = (uint16_t)(U + 1);
                    wr8(X, B);                       /* LC4D3 */
                    X = (uint16_t)(X + 1);
                    M8(TMPCNT) = (uint8_t)(M8(TMPCNT) - 1); /* LC4D5 */
                    CYC(22);
                } while (M8(TMPCNT) != 0);           /* LC4D8  EQEND   */
            }
            A = hw_rd8(RESETS);                      /* LC4DA */
            A &= 0x01;                               /* LC4DD  TEST NOVRAM? */
            CYC(10);
            if (A != 0) {                            /* LC4DF  IFNE  YES */
                CYC(8);
                JSR(eetst);                          /* LC4E1  TEST STORE-ABILITY OF NOVRAM */
            }
            D = 0x0000;                              /* LC4E4  CLEAR RESET BYTE */
            CYC(3);
            hw_wr16(RESETS, D);                      /* LC4E7 */
            CYC(6);
        }
    }
    CYC(5);
    RTS;                                             /* LC4EA */
}

/* EEOPT1 ($C4EB) - MAKE CHANGES TO OPTIONS
 */
void eeopt1(void)
{
    CK(0xC4EB);
    B = M8(FRAME+1);                                 /* LC4EB */
    B &= 0x0F;                                       /* LC4ED  NOT TOO QUICK */
    CYC(9);
    if (B == 0) {                                    /* LC4EF  IFEQ   */
        B = M8(SI_RSY);                              /* LC4F1  UP/DOWN */
        CYC(10);
        if (B < 0xD0) {                              /* LC4F6  IFLO  MAY BE NEGATIVE ENOUGH */
            CYC(5);
            if (B > 0x30) {                          /* LC4FA  IFHI  LARGE ENOUGH TO CHANGE */
                /* TSTB */                           /* LC4FC */
                CYC(5);
                if (!(B & 0x80)) {                   /* LC4FD  IFPL  BACK AN OPTION */
                    B = M8(EEINDX);                  /* LC4FF */
                    B = (uint8_t)(B - 1);            /* LC502 */
                    CYC(10);
                    if ((B & 0x80)) {                /* LC503  IFMI  WRAP WHEN BELOW 0 */
                        B = (T_OPTZ-T_OPT-1);        /* LC505 */
                        CYC(2);
                    }
                    M8(EEINDX) = B;                  /* LC507 */
                    CYC(8);
                } else {                             /* LC50A  ELSE  FORWARD AN OPTION */
                    B = M8(EEINDX);                  /* LC50C */
                    B = (uint8_t)(B + 1);            /* LC50F */
                    CYC(12);
                    if (B > (T_OPTZ-T_OPT-1)) {      /* LC512  IFHI  WRAP */
                        B = 0x00;                    /* LC514 */
                        CYC(2);
                    }
                    M8(EEINDX) = B;                  /* LC516 */
                    CYC(5);
                }
            }
        }
    }
    X = T_OPT;                                       /* LC519  GET OPTION DESCRIPTOR */
    A = M8(EEINDX);                                  /* LC51C */
    B = rd8((uint16_t)(X + (int8_t)A));              /* LC51F */
    M8(TEMP+2) = B;                                  /* LC521 */
    B = (uint8_t)(B >> 1);                           /* LC524 */
    B = (uint8_t)(B >> 1);                           /* LC525 */
    B = (uint8_t)(B >> 1);                           /* LC526 */
    B &= 0x03;                                       /* LC527  FIELD SIZE */
    X = EEMASK;                                      /* LC529 */
    A = rd8((uint16_t)(X + (int8_t)B));              /* LC52C  MASK FOR THIS FIELD SIZE */
    M8(TEMP) = A;                                    /* LC52E  ALSO MAX VALUE FOR CURRENT OPTION */
    /* LEFT FIRE BUTTON CHANGES THE OPTION */
    B = M8(GN_SWE);                                  /* LC531  LOOK FOR EDGE OF LEFT FIRE BUTTON */
    B &= LFIRBT;                                     /* LC533 */
    CYC(48);
    if (B != 0) {                                    /* LC535  IFNE  FOUND AN EDGE */
        B = M8(EEVAL);                               /* LC537  CURRENT VALUE */
        B = (uint8_t)(B + 1);                        /* LC53A  NEXT VALUE, MAYBE */
        cmp8(B, M8(TEMP));                           /* LC53B  PAST MAX? */
        CYC(15);
        if (!(CCC | CCZ)) {                          /* LC53E  IFHI  YES, WRAP BACK TO LOWEST VALUE */
            B = 0x00;                                /* LC540 */
            CYC(2);
        }
        M8(EEVAL) = A;                               /* LC542 */
        A = M8(TEMP+2);                              /* LC545  OPTION DESCRIPTOR */
        A = rol8(A);                                 /* LC548  GET BIT POSITION */
        A = rol8(A);                                 /* LC549 */
        A = rol8(A);                                 /* LC54A */
        A = rol8(A);                                 /* LC54B */
        A &= 0x07;                                   /* LC54C */
        CYC(20);
        for (;;) {
            CK(0xC54E);
            A = (uint8_t)(A - 1);                    /* LC54E */
            CYC(5);
            if ((A & 0x80)) goto l_eeopt1_20;        /* LC54F */
            B = (uint8_t)(B << 1);                   /* LC551  SHIFT DATA */
            M8(TEMP) = (uint8_t)(M8(TEMP) << 1);     /* LC552  SHIFT MASK */
            CYC(12);
        }                                            /* LC555  LOOP   */
l_eeopt1_20:;
        CK(0xC557);
        A = M8(TEMP+2);                              /* LC557  OPTION DESCRIPTOR */
        A &= 0x07;                                   /* LC55A  INDEX INTO OPTION SWITCH AREA */
        A = (uint8_t)(A << 1);                       /* LC55C  NIBBLES, NIBBLES, NIBBLES. I'VE GOT TO REMEMBER NIBBLES */
        X = OPTS0;                                   /* LC55D */
        X = (uint16_t)(X + (int8_t)A);               /* LC560  POINTER TO OPTION SWITCH DATA */
        CYC(17);
        A = rd8(X);                                  /* LC562  GET THE DATA INTO TEMP STORAGE */
        A = (uint8_t)(A << 1);                       /* LC564  HIGH NIBBLE */
        A = (uint8_t)(A << 1);                       /* LC565 */
        A = (uint8_t)(A << 1);                       /* LC566 */
        A = (uint8_t)(A << 1);                       /* LC567 */
        M8(TEMP+1) = A;                              /* LC568 */
        CYC(17);
        A = rd8((uint16_t)(X + 1));                  /* LC56B  LO NIBBLE */
        A &= 0x0F;                                   /* LC56D */
        A = (uint8_t)(A + M8(TEMP+1));               /* LC56F */
        M8(TEMP+1) = A;                              /* LC572 */
        B ^= M8(TEMP+1);                             /* LC575  PUT NEW DATA INTO TEMP */
        B &= M8(TEMP);                               /* LC578 */
        B ^= M8(TEMP+1);                             /* LC57B */
        CYC(32);
        wr8((uint16_t)(X + 1), B);                   /* LC57E  PUT IT BACK INTO EEROM */
        B = (uint8_t)(B >> 1);                       /* LC580 */
        B = (uint8_t)(B >> 1);                       /* LC581 */
        B = (uint8_t)(B >> 1);                       /* LC582 */
        B = (uint8_t)(B >> 1);                       /* LC583 */
        CYC(13);
        wr8(X, B);                                   /* LC584 */
        A = NAREA;                                   /* LC586  SET CHECKSUM */
        CYC(14);
        JSR(eecksm);                                 /* LC588 */
        X = EEROM;                                   /* LC58B  MOV EEROM TO EEBUF TO PREPARE FOR "EEINI1" */
        U = EEBUF;                                   /* LC58E */
        CYC(6);
        do {
            CK(0xC591);
            D = rd16(X);                             /* LC591 */
            X = (uint16_t)(X + 2);
            wr16(U, D);                              /* LC593 */
            U = (uint16_t)(U + 2);
            CYC(23);
        } while (X < (EEROM+0xFF));                  /* LC598  HSEND   */
        CYC(8);
        JSR(eeini1);                                 /* LC59A  SETUP BACKUP AND CHECK OTHER AREAS */
        A = M8(EEINDX);                              /* LC59D  DISPLAY THE NEW VALUE */
        CYC(13);
        JSR(eeopt3);                                 /* LC5A0 */
    }
    CYC(5);
    RTS;                                             /* LC5A3 */
}

/* EEOPT3 ($C5A4) - OUTPUT OPTION VALUE
 */
void eeopt3(void)
{
    CK(0xC5A4);
    X = T_OPT;                                       /* LC5A4 */
    B = rd8((uint16_t)(X + (int8_t)A));              /* LC5A7  OPTION SWITCH DESCRIPTOR */
    M8(TEMP) = B;                                    /* LC5A9  SAVE IT */
    B &= 0x07;                                       /* LC5AC  WHICH WORD? */
    X = OPTS0;                                       /* LC5AE */
    B = (uint8_t)(B << 1);                           /* LC5B1  NIBBLES REMEMBER */
    X = (uint16_t)(X + B);                           /* LC5B2  POINTER TO OPTION SWITCHES */
    B = M8(TEMP);                                    /* LC5B3  SWITCH DESCRIPTOR */
    B = (uint8_t)(B >> 1);                           /* LC5B6 */
    B = (uint8_t)(B >> 1);                           /* LC5B7 */
    B = (uint8_t)(B >> 1);                           /* LC5B8 */
    M8(TEMP) = B;                                    /* LC5B9  SAVE IT */
    B &= 0x03;                                       /* LC5BC  WHAT IS THE FIELD SIZE? */
    U = EEMASK;                                      /* LC5BE */
    U = (uint16_t)(U + (int8_t)B);                   /* LC5C1  ADD B TO U, POINTS TO FIELD MASK */
    B = M8(TEMP);                                    /* LC5C3 */
    B = (uint8_t)(B >> 1);                           /* LC5C6 */
    B = (uint8_t)(B >> 1);                           /* LC5C7 */
    M8(TEMP) = B;                                    /* LC5C8  BIT POSITION OF FIELD */
    CYC(63);
    B = rd8(X);                                      /* LC5CB  GET OPTION SWITCH DATA (BOTH NIBBLES) */
    B = (uint8_t)(B << 1);                           /* LC5CD */
    B = (uint8_t)(B << 1);                           /* LC5CE */
    B = (uint8_t)(B << 1);                           /* LC5CF */
    B = (uint8_t)(B << 1);                           /* LC5D0 */
    M8(TEMP+1) = B;                                  /* LC5D1 */
    CYC(17);
    B = rd8((uint16_t)(X + 1));                      /* LC5D4 */
    B &= 0x0F;                                       /* LC5D6 */
    B = (uint8_t)(B + M8(TEMP+1));                   /* LC5D8 */
    CYC(12);
    for (;;) {
        CK(0xC5DB);
        M8(TEMP) = (uint8_t)(M8(TEMP) - 1);          /* LC5DB */
        CYC(10);
        if ((M8(TEMP) & 0x80)) goto l_eeopt3_20;     /* LC5DE */
        B = (uint8_t)(B >> 1);                       /* LC5E0 */
        CYC(5);
    }                                                /* LC5E1  LOOP   */
l_eeopt3_20:;
    CK(0xC5E3);
    B &= rd8(U);                                     /* LC5E3  MASK FOR FIELD */
    M8(EEVAL) = B;                                   /* LC5E5 */
    X = T_MOPV;                                      /* LC5E8  OPTION SWITCH VALUE MESSAGE TABLE */
    X = (uint16_t)(X + (int8_t)A);                   /* LC5EB  INDEX INTO TABLE--BASE MESSAGE # */
    B = (uint8_t)(B + rd8(X));                       /* LC5ED  MESSAGE NUMBER OF THIS VALUE */
    CYC(25);
    domes2(); return;                                /* LC5EF  COLOR MUST BE ALREADY SET UP */
}

/* EETST ($C5F2) - TEST STORE-ABILITY OF NOVRAM
 */
void eetst(void)
{
    CK(0xC5F2);
    X = EEROM;                                       /* LC5F2  COPY CURRENT DATA TO BUFFER */
    U = EEBUF;                                       /* LC5F5 */
    CYC(6);
    do {
        CK(0xC5F8);
        D = rd16(X);                                 /* LC5F8 */
        X = (uint16_t)(X + 2);
        wr16(U, D);                                  /* LC5FA */
        U = (uint16_t)(U + 2);
        CYC(23);
    } while (X < EEROMZ);                            /* LC5FF  HSEND   */
    X = EEROM;                                       /* LC601  COMPLIMENT THE DATA PRIOR TO STORE */
    CYC(3);
    do {
        CK(0xC604);
        A = rd8(X);                                  /* LC604 */
        A = (uint8_t)~A;                             /* LC606 */
        CYC(6);
        wr8(X, A);                                   /* LC607 */
        X = (uint16_t)(X + 1);
        CYC(13);
    } while (X < EEROMZ);                            /* LC60C  HSEND   */
    hw_wr8(NSTORE, A);                               /* LC60E  STORE IT OUT TO ROM PORTION OF EEROM */
    CYC(13);
    JSR(eewait);                                     /* LC611  WAIT 10 MS FOR THE STORE */
    CYC(8);
    JSR(eeclr);                                      /* LC614  CLEAR IT OUT TO TEST THE RECALL */
    CYC(8);
    JSR(novrcl);                                     /* LC617  RECALL THE DATA */
    /* DATA IN RAM SHOULD BE COMPLIMENT OF BUFFER DATA */
    X = EEROM;                                       /* LC61A  COMPLIMENT IT AGAIN */
    CYC(3);
    do {
        CK(0xC61D);
        A = rd8(X);                                  /* LC61D */
        A = (uint8_t)~A;                             /* LC61F */
        wr8(X, A);                                   /* LC620 */
        X = (uint16_t)(X + 1);
        CYC(19);
    } while (X < EEROMZ);                            /* LC625  HSEND   */
    /* SHOULD BE THE ORIGINAL DATA AGAIN */
    hw_wr8(NSTORE, A);                               /* LC627  STORE IT OUT AGAIN */
    CYC(13);
    JSR(eewait);                                     /* LC62A  WAIT 10 MS FOR STORE */
    CYC(8);
    JSR(eecmp);                                      /* LC62D  COMPARE DATA TO BUFFER */
    CYC(3);
    if (!CCZ) { restor(); return; }                  /* LC630  BAD DATA--SET FLAG AND RESTORE WITH BUFFER DATA */
    /* TWICE COMPLIMENTED DATA LOOKS OK, TRY RECALLING THE DATA AGAIN */
    CYC(8);
    JSR(eeclr);                                      /* LC632  CLEAR IT TO TEST RECALL */
    CYC(8);
    JSR(novrcl);                                     /* LC635  RECALL THE DATA AGAIN */
    CYC(8);
    JSR(eecmp);                                      /* LC638  ONE LAST COMPARE */
    CYC(3);
    if (!CCZ) {                                      /* LC63B  IFNE   */
        CYC(4);
        restor(); return;                            /* LC63D  PUT THE RAM PORTION BACK IF POSSIBLE */
    }
    CYC(5);
    RTS;                                             /* LC640 */
}

/* EECMP ($C641) - COMPARE DATA TO BUFFER
 * Condition codes out: Z.
 */
void eecmp(void)
{
    CK(0xC641);
    X = EEROM;                                       /* LC641 */
    U = EEBUF;                                       /* LC644 */
    CYC(6);
    do {
        CK(0xC647);
        A = rd8(X);                                  /* LC647 */
        X = (uint16_t)(X + 1);
        A ^= rd8(U);                                 /* LC649 */
        U = (uint16_t)(U + 1);
        A = and8(A, 0x0F);                           /* LC64B  LOW NIBBLE ONLY */
        CYC(17);
        if (!CCZ) goto l_eecmp_10;                   /* LC64D */
        CYC(7);
    } while (X < EEROMZ);                            /* LC652  HSEND   */
    A = 0x01;                                        /* LC654  SET FLAG TO SAY NOVRAM OK */
    M8(NVTSTR) = A;                                  /* LC656 */
    A = 0; clrf();                                   /* LC659  SET CONDTION CODE FOR NO ERROR ( Z=1 ) */
    CYC(9);
l_eecmp_10:;
    CK(0xC65A);
    CYC(5);
    RTS;                                             /* LC65A */
}

/* RESTOR ($C65B) - PUT THE RAM PORTION BACK IF POSSIBLE
 */
void restor(void)
{
    CK(0xC65B);
    X = (uint16_t)(X - 1);                           /* LC65B  DID POST ADD ABOVE */
    D = X;                                           /* LC65D  ADDRESS OF ERROR */
    wr16(NVADDR, D);                                 /* LC65F  FOR REPORTING ERROR */
    A = 0xFF;                                        /* LC662  FLAG SAYING NOVRAM BAD */
    M8(NVTSTR) = A;                                  /* LC664  TEST RESULTS */
    X = EEROM;                                       /* LC667  COPY BUFFER TO EEROM RAM */
    U = EEBUF;                                       /* LC66A */
    CYC(30);
    do {
        CK(0xC66D);
        D = rd16(U);                                 /* LC66D */
        U = (uint16_t)(U + 2);
        wr16(X, D);                                  /* LC66F */
        X = (uint16_t)(X + 2);
        CYC(23);
    } while (X < EEROMZ);                            /* LC674  HSEND   */
    /* TST NVTSTR */                                 /* LC676  SET CONDITION CODES */
    CYC(12);
    RTS;                                             /* LC679 */
}

/* EECLR ($C67A) - CLEAR IT OUT TO TEST THE RECALL
 */
void eeclr(void)
{
    CK(0xC67A);
    X = EEROM;                                       /* LC67A */
    D = 0x0000;                                      /* LC67D */
    CYC(6);
    do {
        CK(0xC680);
        wr16(X, D);                                  /* LC680 */
        X = (uint16_t)(X + 2);
        CYC(15);
    } while (X < EEROMZ);                            /* LC685  HSEND   */
    CYC(5);
    RTS;                                             /* LC687 */
}

/* EEWAIT ($C688) - WAIT 10 MS FOR THE STORE
 */
void eewait(void)
{
    CK(0xC688);
    X = 0x07D0;                                      /* LC688  10. MS = 15000. CYCLES/8 CYCLES = 1875. */
    CYC(3);
    do {
        CK(0xC68B);
        X = (uint16_t)(X - 1);                       /* LC68B  DEX */
        CYC(8);
    } while (X != 0);                                /* LC68D  EQEND   */
    CYC(5);
    RTS;                                             /* LC68F */
}

/* EETSTR ($C690) - REPORT RESULTS OF EEROM ( NOVRAM ) TEST
 */
void eetstr(void)
{
    CK(0xC690);
    A = M8(NVTSTR);                                  /* LC690  RESULTS OF NOVRAM ( EEROM ) TEST */
    /* 0 MEANS NO TEST PERFORMED */
    /* 1 MEANS NO ERRORS DETECTED */
    /* ANYTHING ELSE MEANS ERRORS DETECTED */
    CYC(8);
    if (A != 0) {                                    /* LC693  IFNE  TEST WAS PERFORMED - TELL RESULTS */
        CYC(5);
        if (A == 0x01) {                             /* LC697  IFEQ  NO ERRORS -- GOOD EEROM */
            B = MS_GNV;                              /* LC699  "NO ERRORS" ( GOOD NOVRAM ) */
            CYC(5);
        } else {                                     /* LC69B  ELSE  THERE WERE ERRORS */
            D = 0x1F6A;                              /* LC69D */
            wr16(Y, D);                              /* LC6A0 */
            Y = (uint16_t)(Y + 2);
            D = 0x01A4;                              /* LC6A2 */
            wr16(Y, D);                              /* LC6A5 */
            Y = (uint16_t)(Y + 2);
            A = M8(NVADDR+1);                        /* LC6A7  LOW BYTE OF ADDRESS OF ERROR */
            CYC(35);
            JSR(vwbyte);                             /* LC6AA */
            D = VGCNTR;                              /* LC6AD */
            wr16(Y, D);                              /* LC6B0 */
            Y = (uint16_t)(Y + 2);
            B = MS_BNV;                              /* LC6B2  "ERROR AT" ( BAD NOVRAM ) */
            CYC(13);
        }
        CYC(8);
        JSR(domess);                                 /* LC6B4 */
    }
    CYC(5);
    RTS;                                             /* LC6B7 */
}

/* NOVRCL ($C6B8) - PERFORM A RECALL OF THE NON-VOLATILE RAM
 */
void novrcl(void)
{
    CK(0xC6B8);
    A = 0xFF;                                        /* LC6B8  D7 = 1 PUTS NOVRAM IN RECALL MODE */
    CYC(2);
    hw_wr8(NVRRCL, A);                               /* LC6BA */
    CYC(13);
    JSR(waitframe);                                  /* LC6BD  WAIT A WHILE, THERE'S A LARGE CAP ON THE LINE */
    A = 0x00;                                        /* LC6C0  D7 = 0 BRINGS US OUT OF RECALL MODE */
    CYC(2);
    hw_wr8(NVRRCL, A);                               /* LC6C2 */
    U = 0x0000;                                      /* LC6C5 */
    CYC(8);
    do {
        CK(0xC6C8);
        CYC(8);
        JSR(waitframe);                              /* LC6C8 */
        U = (uint16_t)(U + 1);                       /* LC6CB */
        CYC(13);
    } while (U < 0x0020);                            /* LC6D1  HSEND  NOW THE NOVRAM SHOULD BE USABLE */
    CYC(5);
    RTS;                                             /* LC6D3 */
}

/* EETEMP ($C6D4) - MOVE 8 NIBBLES IN EEROM TO 4 BYTES OF RAM
 * Condition codes out: NZVC.
 */
void eetemp(void)
{
    CK(0xC6D4);
    U = TEMP;                                        /* LC6D4 */
    CYC(3);
    eetmp2();                                        /* falls into EETMP2 */
}

/* EETMP2 ($C6D7) - MOVE EE TO TEMP
 * Condition codes out: NZVC.
 */
void eetmp2(void)
{
    CK(0xC6D7);
    A = 0x03;                                        /* LC6D7 */
    CYC(2);
    eetmp3();                                        /* falls into EETMP3 */
}

/* EETMP3 ($C6D9) - Move EEROM nibbles at (X) to bytes at (U): A = number of bytes less one, two nibbles (upper, lower)
 *   per byte; uses TMPCNT; ends with LEAX -8,X (restores X only for the 8-nibble EETEMP case)
 * Condition codes out: NZVC.
 */
void eetmp3(void)
{
    CK(0xC6D9);
    M8(TMPCNT) = A;                                  /* LC6D9 */
    CYC(5);
    do {
        CK(0xC6DC);
        A = rd8(X);                                  /* LC6DC  UPPER NIBBLE */
        X = (uint16_t)(X + 1);
        A = (uint8_t)(A << 1);                       /* LC6DE */
        A = (uint8_t)(A << 1);                       /* LC6DF */
        A = (uint8_t)(A << 1);                       /* LC6E0 */
        A = (uint8_t)(A << 1);                       /* LC6E1 */
        wr8(U, A);                                   /* LC6E2 */
        CYC(18);
        A = rd8(X);                                  /* LC6E4  LOWER NIBBLE */
        X = (uint16_t)(X + 1);
        A &= 0x0F;                                   /* LC6E6 */
        A = add8(A, rd8(U));                         /* LC6E8 */
        wr8(U, A);                                   /* LC6EA */
        U = (uint16_t)(U + 1);
        M8(TMPCNT) = dec8(M8(TMPCNT));               /* LC6EC */
        CYC(28);
    } while (!CCN);                                  /* LC6EF  MIEND   */
    X = (uint16_t)(X - 8);                           /* LC6F1  RESTORE X */
    CCZ = (X == 0);
    CYC(10);
    RTS;                                             /* LC6F3 */
}

/* TEMPEE ($C6F4) - PUT IT BACK IN EEROM
 */
void tempee(void)
{
    CK(0xC6F4);
    U = TEMP;                                        /* LC6F4 */
    CYC(3);
    tmpee2();                                        /* falls into TMPEE2 */
}

/* TMPEE2 ($C6F7) - PUT BACK IN EE ROM
 */
void tmpee2(void)
{
    CK(0xC6F7);
    A = 0x02;                                        /* LC6F7 */
    CYC(2);
    tmpee3();                                        /* falls into TMPEE3 */
}

/* TMPEE3 ($C6F9) - PUT DATA BACK TO EEROM
 */
void tmpee3(void)
{
    CK(0xC6F9);
    M8(TMPCNT) = A;                                  /* LC6F9  NUMBER OF BYTES TO MOVE */
    CYC(5);
    do {
        CK(0xC6FC);
        A = rd8(U);                                  /* LC6FC  GET DATA */
        U = (uint16_t)(U + 1);
        CYC(6);
        wr8((uint16_t)(X + 1), A);                   /* LC6FE  STORE LOWER NIBBLE FIRST */
        A = (uint8_t)(A >> 1);                       /* LC700  GET UPPER NIBBLE TO LOWER */
        A = (uint8_t)(A >> 1);                       /* LC701 */
        A = (uint8_t)(A >> 1);                       /* LC702 */
        A = (uint8_t)(A >> 1);                       /* LC703 */
        CYC(13);
        wr8(X, A);                                   /* LC704  STORE UPPER, UPDATE X */
        X = (uint16_t)(X + 2);
        M8(TMPCNT) = (uint8_t)(M8(TMPCNT) - 1);      /* LC706 */
        CYC(17);
    } while (!(M8(TMPCNT) & 0x80));                  /* LC709  MIEND   */
    X = (uint16_t)(X - 6);                           /* LC70B */
    CYC(10);
    RTS;                                             /* LC70D */
}

/* TIME ($C70E) - DISPLAY TIME IN M:S FORMAT
 */
void time_(void)
{
    CK(0xC70E);
    B = 0x00;                                        /* LC70E */
    M8(BT_SUP) = B;                                  /* LC710 */
    B = A;                                           /* LC712 */
    A = (uint8_t)(A >> 1);                           /* LC714 */
    A = (uint8_t)(A >> 1);                           /* LC715 */
    A = (uint8_t)(A >> 1);                           /* LC716 */
    A = (uint8_t)(A >> 1);                           /* LC717 */
    CYC(25);
    if (A >= 0x0A) {                                 /* LC71A  IFHS  MAX OF 9 */
        A = 0x09;                                    /* LC71C */
        CYC(2);
    }
    CYC(8);
    JSR(vwnibl);                                     /* LC71E  MINUTES */
    A = 0xB8;                                        /* LC721  CHANGE TO COLON IF WE MAKE ONE */
    wr8(Y, A);                                       /* LC723 */
    Y = (uint16_t)(Y + 1);
    A = (VJCOLN&0xFF);                               /* LC725 */
    wr8(Y, A);                                       /* LC727 */
    Y = (uint16_t)(Y + 1);
    A = 0;                                           /* LC729 */
    B &= 0x0F;                                       /* LC72A  SECONDS */
    CYC(23);
    if (B != 0) {                                    /* LC72C  IFNE   */
        do {
            CK(0xC72E);
            A = add8(A, 0x04);                       /* LC72E */
            daa_a();                                 /* LC730 */
            B = (uint8_t)(B - 1);                    /* LC731 */
            CYC(9);
        } while (B != 0);                            /* LC732  EQEND   */
    }
    CYC(4);
    vwbyte(); return;                                /* LC734  AND RETURN */
}
